from django.db.models import Avg, Count, Q
from .models import Book


def get_book_list(*, filters=None, user=None):
    """لیست کتاب‌ها با فیلتر و بهینه‌سازی."""
    filters = filters or {}
    qs = (
        Book.objects
        .select_related("author", "category")
        .prefetch_related("categories")
        .annotate(
            reviews_count=Count("reviews", distinct=True),
            average_rating=Avg("reviews__rating"),
        )
    )

    if user and not user.is_staff:
        qs = qs.filter(Q(is_published=True) | Q(owner=user))
    else:
        qs = qs.filter(is_published=True)

    if "category" in filters:
        qs = qs.filter(category__slug=filters["category"])
    if "min_rating" in filters:
        qs = qs.filter(average_rating__gte=filters["min_rating"])
    if "search" in filters:
        qs = qs.filter(
            Q(title__icontains=filters["search"]) |
            Q(description__icontains=filters["search"])
        )

    return qs.order_by("-published_at")


def get_book_detail(*, slug):
    """جزئیات یک کتاب با همه روابط پیش‌بارگذاری‌شده."""
    return (
        Book.objects
        .select_related("author", "category")
        .prefetch_related("categories", "reviews__user")
        .annotate(
            reviews_count=Count("reviews", distinct=True),
            average_rating=Avg("reviews__rating"),
        )
        .get(slug=slug)
    )

class BookViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = BookSerializer
    lookup_field = "slug"

    def get_queryset(self):
        if self.action == "list":
            return get_book_list(
                filters=self.request.query_params,
                user=self.request.user,
            )
        return get_book_detail(slug=self.kwargs["slug"])

